// A. Each objective: what changes, by how much, by when.
const BUSINESS_OBJECTIVES = [
  'Reduce phone calls to the reception desk from about 120 to at most 70 per day within 6 months after release 1.',
  'Reduce the no-show rate from 15% to below 7% within 6 months after release 1.',
  'Have at least 60% of all appointments booked online within 9 months after release 1.',
];

// B. Vision statement — Moore's template (value, not technology).
const VISION = {
  forWho: 'patients of Minh An Family Clinic and its staff',
  who: 'want to book, change and pay for a visit without waiting on the phone',
  productName: 'ClinicCare',
  isA: 'web and mobile appointment and clinic workflow system',
  that: 'lets patients book an appointment online any time and reminds them before the visit',
  unlike: 'phoning the busy reception desk during opening hours',
  ourProduct: 'connects booking, payment, the doctor’s visit and the e-prescription in one place',
};

// C. Scope of release 1 — what is explicitly out is as important as what is in.
const SCOPE = {
  in: ['Patient registration and online booking', 'Cancellation up to 2 hours before', 'Online payment through VNPay', 'Check-in and no-show marking by reception', 'Visit notes and e-prescriptions sent to the national system', 'SMS reminders 24 hours before', 'Services, fees and monthly reports for the manager'],
  out: ['Video consultation', 'Insurance e-claims', 'Loyalty programme', 'Integration with the lab machines'],
};
